import express from 'express';
import { Pool } from 'pg';
import crypto from 'crypto';
import Redis from 'ioredis';

const app = express();
app.use(express.json());

const pool = new Pool({
  connectionString: process.env.DATABASE_URL,
  ssl: { rejectUnauthorized: process.env.NODE_ENV === 'production' }
});

const redis = new Redis(process.env.REDIS_URL);

// Session validation middleware
async function validateSession(req, res, next) {
  const token = req.headers['x-session-token'];
  if (!token) return res.status(401).json({ error: 'missing token' });
  const session = await redis.get(`sess:${token}`);
  if (!session) return res.status(401).json({ error: 'invalid session' });
  req.session = JSON.parse(session);
  next();
}

// User search endpoint - supports flexible filtering
app.get('/api/v2/users/search', validateSession, async (req, res) => {
  try {
    const { department, role, status, sort_by, order } = req.query;

    let baseQuery = 'SELECT id, name, email, department, role, last_login FROM users WHERE 1=1';
    const params = [];
    let paramIdx = 1;

    if (department) {
      params.push(department);
      baseQuery += ` AND department = $${paramIdx++}`;
    }
    if (role) {
      params.push(role);
      baseQuery += ` AND role = $${paramIdx++}`;
    }
    if (status) {
      params.push(status);
      baseQuery += ` AND status = $${paramIdx++}`;
    }

    // Dynamic sort - validated against allowed columns
    const allowedSorts = ['name', 'email', 'department', 'last_login', 'created_at'];
    const sortCol = allowedSorts.includes(sort_by) ? sort_by : 'name';
    const sortOrder = order === 'desc' ? 'DESC' : 'ASC';
    baseQuery += ` ORDER BY ${sortCol} ${sortOrder}`;

    // Pagination
    const limit = Math.min(parseInt(req.query.limit) || 50, 200);
    const offset = parseInt(req.query.offset) || 0;
    baseQuery += ` LIMIT ${limit} OFFSET ${offset}`;

    const result = await pool.query(baseQuery, params);
    res.json({ users: result.rows, total: result.rowCount });
  } catch (err) {
    console.error('Search error:', err.message);
    res.status(500).json({ error: 'search failed' });
  }
});

// Bulk user export - generates CSV
app.post('/api/v2/users/export', validateSession, async (req, res) => {
  try {
    const { user_ids, format, fields } = req.body;

    if (!Array.isArray(user_ids) || user_ids.length === 0) {
      return res.status(400).json({ error: 'user_ids required' });
    }

    // Build field list from request
    const requestedFields = Array.isArray(fields) ? fields : ['id', 'name', 'email'];
    const fieldList = requestedFields.join(', ');

    const placeholders = user_ids.map((_, i) => `$${i + 1}`).join(',');
    const query = `SELECT ${fieldList} FROM users WHERE id IN (${placeholders})`;

    const result = await pool.query(query, user_ids);

    if (format === 'csv') {
      const header = requestedFields.join(',');
      const rows = result.rows.map(r => requestedFields.map(f => r[f]).join(','));
      res.setHeader('Content-Type', 'text/csv');
      res.send([header, ...rows].join('\n'));
    } else {
      res.json({ users: result.rows });
    }
  } catch (err) {
    console.error('Export error:', err.message);
    res.status(500).json({ error: 'export failed' });
  }
});

// Health check with version info
app.get('/health', (req, res) => {
  res.json({ status: 'ok', version: process.env.APP_VERSION || 'dev' });
});

app.listen(3000, () => console.log('User service listening on :3000'));
